import { z } from "zod";

// Shared building blocks for the request validators. Strings are NOT trimmed
// on purpose: validation must never change the value that gets stored.

const ID_PATTERN = /^[A-Za-z0-9-]{1,64}$/;

/** Accepts randomUUID ids and the 32-hex ids generated by the SQL seeds. */
export const idParam = (field: string) =>
  z.string({ error: `Invalid ${field}` }).regex(ID_PATTERN, `Invalid ${field}`);

/** True for a real calendar date written as YYYY-MM-DD. */
function isValidIsoDate(value: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const parsed = new Date(`${value}T00:00:00.000Z`);
  return !Number.isNaN(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value;
}

export const isoDate = (field = "date") => {
  const message = `${field} must be a valid date in YYYY-MM-DD format`;
  return z.string({ error: message }).refine(isValidIsoDate, message);
};

/** Required, non-empty string (empty/missing/wrong type all give `message`). */
export const requiredString = (message: string, label: string, max: number) =>
  z
    .string({ error: message })
    .min(1, message)
    .max(max, `${label} must be at most ${max} characters`);

/**
 * Optional non-empty string for partial updates: omitted or null keeps the
 * current value (the models treat null as "omitted"), "" is rejected.
 */
export const optionalNonEmptyString = (message: string, label: string, max: number) =>
  requiredString(message, label, max).nullish();

/** Optional free-text string (may be empty). */
export const optionalString = (label: string, max: number) =>
  z
    .string({ error: `${label} must be a string` })
    .max(max, `${label} must be at most ${max} characters`)
    .nullish();

/** Optional date; null counts as omitted, like before. */
export const optionalDate = (field = "date") => isoDate(field).nullish();

/**
 * Optional boolean. `null` is accepted here, but the models store a null
 * `completed` as false (pre-existing behavior, kept on purpose): only an
 * omitted field leaves the stored value untouched.
 */
export const optionalBoolean = (field: string) =>
  z.boolean({ error: `${field} must be a boolean` }).nullish();

const maxMessage = (field: string, max: number) =>
  `${field} must be less than or equal to ${max}`;

/** Finite number in [0, max] (z.number() already rejects NaN/Infinity). */
export const nonNegative = (field: string, max: number) =>
  z
    .number({ error: `${field} must be a number` })
    .min(0, `${field} must be greater than or equal to 0`)
    .max(max, maxMessage(field, max))
    .nullish();

export const nonNegativeInt = (field: string, max: number) =>
  z
    .number({ error: `${field} must be a number` })
    .int(`${field} must be an integer`)
    .min(0, `${field} must be greater than or equal to 0`)
    .max(max, maxMessage(field, max))
    .nullish();

/** Finite number in (0, max]. */
export const positive = (field: string, max: number) =>
  z
    .number({ error: `${field} must be a number` })
    .gt(0, `${field} must be greater than 0`)
    .max(max, maxMessage(field, max))
    .nullish();

/** Bodies must be JSON objects; unknown keys are stripped (zod default). */
export const bodyObject = <T extends z.ZodRawShape>(shape: T) =>
  z.object(shape, { error: "Request body must be a JSON object" });
